  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 17, $j$5.1 The Atmosphere$j$, $j${"readings": [{"title": "Isaiah 40 (King James Version)", "url": "/portal/bible/Isaiah/40"}], "body": "The atmosphere is the blanket of gases that surrounds Earth. Isaiah 40:22 says of God, It is he that sitteth upon the circle of the earth, and the inhabitants thereof are as grasshoppers; that stretcheth out the heavens as a curtain, and spreadeth them out as a tent to dwell in. The air we breathe is a gift that makes life on Earth possible.\n\nDry air is about 78 percent nitrogen and 21 percent oxygen, with about 0.9 percent argon and a trace of carbon dioxide, about 0.04 percent. Air also holds water vapor in amounts that vary from place to place. Gravity holds the atmosphere close to Earth, so most of the air is in the lowest few kilometers. Air pressure is the force of the air pressing on a surface. At sea level it is about 101.3 kilopascals, which is also called one atmosphere, and it falls as altitude rises. At the top of a high mountain the pressure is about half of sea level, which is why climbers need extra oxygen. A barometer measures air pressure.\n\nThe atmosphere has layers based on temperature. The troposphere is the lowest layer. It reaches about 12 kilometers high on average, holds most of the air and nearly all the water vapor, and is where weather happens. The temperature falls about 6.5 degrees Celsius for each kilometer of height. Above it is the stratosphere, up to about 50 kilometers, where jets fly. The temperature rises with height because the ozone layer absorbs ultraviolet light from the Sun. The mesosphere, up to about 85 kilometers, is the coldest layer, and meteors burn up in it. The thermosphere extends to several hundred kilometers. It has very little air, it can be extremely hot, and it holds the aurora and the International Space Station. The exosphere fades into space.\n\nOzone is a form of oxygen with three atoms, and the ozone layer in the stratosphere protects living things from harmful ultraviolet radiation. In the 1980s scientists found an ozone hole over Antarctica caused by chemicals called CFCs, which were used in refrigerators and spray cans. The nations of the world agreed to stop using them in the Montreal Protocol of 1987, and the ozone layer is slowly recovering. It is an example of nations working together to solve a problem.\n\nYour task: (1) Give the main gases in the air. (2) Order the layers of the atmosphere and tell one feature of each. (3) Explain why the ozone layer matters.\n\nFlorida standards: SC.912.E.7.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SC.912.E.7", "script": "Welcome back. Listen, Isaiah 40:22 says of God, It is he that sitteth upon the circle of the earth, that stretcheth out the heavens as a curtain. The air we breathe is a gift that makes life possible.\n\nNow watch this. Dry air is about 78 percent nitrogen and 21 percent oxygen, with a little argon and a trace of carbon dioxide. Air pressure is about 101.3 kilopascals at sea level and falls as you go higher. A barometer measures it.\n\nLook at the layers. The troposphere is the lowest, about 12 kilometers on average, and holds our weather. The stratosphere is next, up to about 50 kilometers. It has the ozone layer, so the temperature rises with height. The mesosphere is the coldest layer, and meteors burn up in it. The thermosphere holds the aurora and the space station. The exosphere fades into space.\n\nOzone in the stratosphere absorbs harmful ultraviolet light. In the 1980s, scientists found an ozone hole caused by CFCs. Nations agreed in the Montreal Protocol of 1987 to stop using them, and the ozone layer is recovering.\n\nYour task is to name the gases, order the layers and explain why ozone matters. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$5.1 The Atmosphere$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 18, $j$5.2 Energy, Wind and Global Circulation$j$, $j${"readings": [{"title": "Ecclesiastes 1 (King James Version)", "url": "/portal/bible/Ecclesiastes/1"}], "body": "Wind is moving air, and it carries heat and moisture around the world. Ecclesiastes 1:6 says, The wind goeth toward the south, and turneth about unto the north; it whirleth about continually, and the wind returneth again according to his circuits. Thousands of years ago, the Preacher described a pattern we now study as global circulation.\n\nThe Sun is the source of almost all energy for the atmosphere. About half of the sunlight that reaches Earth is absorbed by the land and oceans, and the rest is reflected or absorbed in the air. The warmed surface heats the air above it by conduction, convection and radiation. The greenhouse effect is a natural process in which gases such as water vapor and carbon dioxide absorb some of the heat Earth radiates and send part of it back. Without this natural effect, Earth would be much too cold for life.\n\nSunlight strikes the equator more directly than the poles, so Earth is heated unevenly. Warm air is less dense and rises, which makes an area of low pressure. Cool air is denser and sinks, which makes high pressure. Wind is air moving from high pressure to low pressure. The greater the pressure difference, the stronger the wind.\n\nLocal winds are easy to see in Florida. During the day, land heats faster than the ocean, so warm air rises over land and cooler air flows in from the sea. This is a sea breeze. At night the land cools faster, and the flow reverses into a land breeze. Florida's summer sea breezes from both coasts meet in the middle of the state and help power afternoon thunderstorms.\n\nGlobal winds are shaped by Earth's rotation, which bends moving air to the right in the Northern Hemisphere and to the left in the Southern Hemisphere. This bending is called the Coriolis effect. The result is great wind belts. The trade winds blow from east to west near the equator and helped sailing ships cross the Atlantic. The prevailing westerlies blow from west to east in the middle latitudes, where Florida's weather systems usually move. The polar easterlies blow near the poles. Fast, narrow bands of wind high in the troposphere, called jet streams, steer storms.\n\nYour task: (1) Explain what causes wind. (2) Describe a sea breeze. (3) Name the three global wind belts and the Coriolis effect.\n\nFlorida standards: SC.912.E.7.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SC.912.E.7", "script": "Welcome back. Listen, Ecclesiastes 1:6 says, The wind goeth toward the south, and turneth about unto the north; it whirleth about continually, and the wind returneth again according to his circuits. Long ago the Preacher described a pattern we now study as global circulation.\n\nNow watch this. The Sun is the source of nearly all energy for the atmosphere. The greenhouse effect is natural. Gases like water vapor and carbon dioxide hold some heat, and without it Earth would be too cold for life.\n\nSunlight heats the equator more than the poles. Warm air is less dense and rises, making low pressure. Cool air sinks, making high pressure. Wind is air moving from high pressure to low pressure.\n\nLook at Florida. In the daytime land heats faster than the sea, so cool air flows in as a sea breeze. At night it reverses into a land breeze. Sea breezes from both coasts meet in the middle of the state and help build afternoon thunderstorms.\n\nEarth's rotation bends winds. That is the Coriolis effect. It makes the trade winds near the equator, the westerlies in the middle latitudes and the polar easterlies. Jet streams steer storms.\n\nYour task is to explain wind, describe a sea breeze and name the wind belts. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$5.2 Energy, Wind and Global Circulation$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 19, $j$5.3 Water in the Air: Clouds, Precipitation and Fronts$j$, $j${"readings": [{"title": "Job 36 (King James Version)", "url": "/portal/bible/Job/36"}], "body": "Water moves through the air, land and sea in a continuous cycle. Job 36:27 says of God, For he maketh small the drops of water: they pour down rain according to the vapour thereof. Ecclesiastes 1:7 adds that all the rivers run into the sea, yet the sea is not full. The water cycle is one of God's great design features.\n\nIn the water cycle, the Sun's heat causes evaporation, which turns liquid water into water vapor. Plants release water vapor through transpiration. As the vapor rises and cools, it changes back into liquid droplets in condensation, and clouds form. Water falls as precipitation, which can be rain, snow, sleet or hail. The water then flows over the land as runoff or soaks into the ground as groundwater, and eventually returns to the ocean.\n\nHumidity is the amount of water vapor in the air. Relative humidity is the amount of vapor compared with the most the air could hold at that temperature. Warm air can hold more vapor than cold air. The dew point is the temperature at which air becomes saturated and vapor begins to condense. Dew forms on grass when the temperature falls to the dew point. In Florida the dew point is often high in summer, which is why the air feels sticky.\n\nClouds are classified by shape and height. Cumulus clouds are puffy and white. Stratus clouds form flat gray layers. Cirrus clouds are thin and wispy and high up. Cumulonimbus clouds are towering storm clouds that produce thunderstorms. The prefix nimbo or the word nimbus means rain.\n\nWeather is also shaped by air masses and fronts. An air mass is a large body of air with similar temperature and humidity. A front is the boundary where two different air masses meet. At a cold front, cold air pushes under warm air and lifts it quickly, often making heavy showers and thunderstorms followed by cooler, drier weather. At a warm front, warm air slides up over cold air and brings steady rain. A stationary front does not move much. An occluded front forms when a cold front overtakes a warm front. On a weather map, high pressure (H) usually brings clear skies and low pressure (L) usually brings clouds and precipitation.\n\nYour task: (1) Trace the steps of the water cycle. (2) Define dew point and humidity. (3) Describe what happens at a cold front.\n\nFlorida standards: SC.912.E.7.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SC.912.E.7", "script": "Welcome back. Listen, Job 36:27 says of God, For he maketh small the drops of water: they pour down rain according to the vapour thereof. The water cycle is one of God's great design features.\n\nNow watch this. The Sun's heat causes evaporation. Plants release vapor through transpiration. Rising vapor cools and condenses into clouds. Water falls as precipitation, flows over the land as runoff or soaks in as groundwater, and returns to the ocean.\n\nHumidity is the amount of water vapor in the air. Warm air holds more than cold air. The dew point is the temperature where air becomes saturated and vapor condenses. In a Florida summer the dew point is high, so the air feels sticky.\n\nLook at clouds. Cumulus are puffy. Stratus are flat gray layers. Cirrus are thin and high. Cumulonimbus are towering storm clouds.\n\nA front is the boundary between air masses. At a cold front, cold air lifts warm air quickly, bringing showers and thunderstorms and then cooler, drier air. At a warm front, warm air slides over cold air and brings steady rain. High pressure usually means clear skies. Low pressure usually means clouds and rain.\n\nYour task is to trace the water cycle, define dew point and humidity and describe a cold front. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$5.3 Water in the Air: Clouds, Precipitation and Fronts$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 20, $j$5.4 Severe Weather, Hurricanes and Safety$j$, $j${"readings": [{"title": "Mark 4 (King James Version)", "url": "/portal/bible/Mark/4"}], "body": "Severe weather can be dangerous, and God is greater than any storm. Mark 4:39 says that Jesus rebuked the wind, and said unto the sea, Peace, be still. And the wind ceased, and there was a great calm. Psalm 107:29 says, He maketh the storm a calm, so that the waves thereof are still. Believers respect storms and also prepare wisely.\n\nA thunderstorm forms when warm, moist air rises quickly and builds a cumulonimbus cloud. Lightning is a giant spark of electricity between charges in clouds or the ground, and thunder is the sound of the air heated by the bolt. You can count the seconds between the flash and the thunder, and divide by 5 to estimate the distance in miles. Florida has more thunderstorm days than most states. The safe rule is, when thunder roars, go indoors, and wait at least 30 minutes after the last thunder before going back outside. A tornado is a rotating column of air that touches the ground. Its strength is rated on the Enhanced Fujita scale from EF0 to EF5. Tornadoes in Florida are often weak and short lived, and some form inside hurricanes.\n\nA hurricane is a huge rotating storm that forms over warm tropical ocean water, at least about 26.5 degrees Celsius (80 degrees Fahrenheit). In the Atlantic it is called a hurricane, and in the Pacific a typhoon. A tropical storm has winds of 39 to 73 miles per hour. A hurricane has winds of 74 miles per hour or more. The Saffir Simpson scale rates hurricanes from Category 1 (74 to 95 miles per hour) to Category 5 (157 miles per hour or more). Winds spiral counterclockwise in the Northern Hemisphere. At the center is the calm eye, surrounded by the strongest winds in the eyewall. The Atlantic hurricane season runs from June 1 to November 30, and activity peaks in late summer.\n\nStorm surge, the rise of seawater pushed ashore by the winds, is usually the most deadly part of a hurricane. Heavy rain also brings flooding far inland. In 1992, Hurricane Andrew struck south Florida as a Category 5 and caused enormous damage, and it led to stricter building codes. A hurricane watch means hurricane conditions are possible within about 48 hours, and a warning means they are expected within about 36 hours.\n\nPreparation saves lives. Know your evacuation zone, follow local officials, keep a disaster kit with at least three to seven days of water (one gallon per person per day), food, medicine, flashlights, batteries and important papers, secure your home and make a family plan. Never drive through flooded roads. Turn around, do not drown.\n\nYour task: (1) Explain what a hurricane needs to form. (2) Tell the difference between a watch and a warning. (3) List five items for a family disaster kit.\n\nFlorida standards: SC.912.E.7.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SC.912.E.7", "script": "Welcome back. Listen, Mark 4:39 says that Jesus rebuked the wind, and said unto the sea, Peace, be still. And the wind ceased, and there was a great calm. God is greater than any storm, and believers respect storms and prepare wisely.\n\nNow watch this. A thunderstorm forms when warm, moist air rises and builds a cumulonimbus cloud. When thunder roars, go indoors, and wait 30 minutes after the last thunder. Tornadoes are rated EF0 to EF5.\n\nA hurricane forms over warm ocean water, at least about 26.5 degrees Celsius. A tropical storm has winds of 39 to 73 miles per hour. A hurricane has winds of 74 or more. The Saffir Simpson scale runs from Category 1 to Category 5, which is 157 miles per hour or more. The eye is calm, and the eyewall has the strongest winds. The Atlantic season runs from June 1 to November 30.\n\nStorm surge is usually the most deadly part. Hurricane Andrew in 1992 struck south Florida as a Category 5 and led to stricter building codes. A watch means hurricane conditions are possible within about 48 hours. A warning means they are expected within about 36 hours.\n\nPrepare. Know your evacuation zone. Keep at least three to seven days of water, one gallon per person per day, food, medicine, flashlights, batteries and papers. Turn around, do not drown.\n\nYour task is to explain how hurricanes form, tell a watch from a warning and list kit items. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$5.4 Severe Weather, Hurricanes and Safety$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 5, $j$Assessment 5: The Atmosphere and Weather$j$, $j${"prompt": "Write a report of at least 250 words on the atmosphere and weather. Use complete sentences, show every calculation and label each part. Psalm 107:29 says, He maketh the storm a calm, so that the waves thereof are still.\n\nPart 1: Give the main gases in the atmosphere with their approximate percentages. Order the layers of the atmosphere from the ground up and describe one feature of each. Explain why the ozone layer matters and what the Montreal Protocol did.\nPart 2: Explain how uneven heating causes wind, describe a sea breeze and tell why Florida gets afternoon thunderstorms in summer. Name the three global wind belts and explain the Coriolis effect.\nPart 3: Trace the water cycle with at least five processes. Explain humidity and dew point, and compare cumulus, stratus and cirrus clouds.\nPart 4: Describe a cold front, a warm front and the weather each brings. Explain what high pressure and low pressure usually mean on a weather map.\nPart 5: Explain how a hurricane forms, what the Saffir Simpson scale measures, and why storm surge is so dangerous. Describe a family hurricane plan with five supplies or actions, and explain how Mark 4:39 and wise preparation fit together.", "rubric": "100 points. Part 1: 20 points. Part 2: 20 points. Part 3: 20 points. Part 4: 15 points. Part 5: 20 points. Complete sentences and conventions: 5 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 5: The Atmosphere and Weather$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 5, $j$Discussion 5: Peace in the Storm$j$, $j${"prompt": "Write a post of at least 120 words that (1) describes a storm, a hurricane or severe weather you have experienced or heard about and how your family prepared, (2) explains in your own words how one weather process works, such as the water cycle, a sea breeze or a hurricane, (3) explains how trusting God and preparing wisely work together, and (4) connects your answer to Mark 4:39, Psalm 107:29 or Job 36:27. Then write a respectful reply of at least 40 words to another student's post, or answer this question: How can a church help neighbors before and after a hurricane? Keep your tone kind and respectful of other views."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 5: Peace in the Storm$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 21, $j$Check 5.1: The Atmosphere$j$, $j${"questions": [{"q": "The most abundant gas in Earth's atmosphere is:", "options": ["Carbon dioxide", "Nitrogen", "Oxygen", "Argon"]}, {"q": "Weather occurs mainly in the:", "options": ["Stratosphere", "Troposphere", "Thermosphere", "Mesosphere"]}, {"q": "The ozone layer is located in the:", "options": ["Stratosphere", "Troposphere", "Exosphere", "Mesosphere"]}, {"q": "As altitude increases, air pressure:", "options": ["Doubles", "Stays the same", "Increases", "Decreases"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.1: The Atmosphere$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,1,0,3}'::int[], array[$j$Nitrogen is about 78 percent of dry air.$j$,$j$The troposphere holds most of the air and water vapor.$j$,$j$It absorbs ultraviolet light there.$j$,$j$There is less air above you.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.1: The Atmosphere$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 22, $j$Check 5.2: Energy, Wind and Global Circulation$j$, $j${"questions": [{"q": "Wind is the movement of air from:", "options": ["High pressure to low pressure", "The ocean to the land only", "The poles to the equator only", "Low pressure to high pressure"]}, {"q": "A sea breeze blows during the day from the:", "options": ["Mountain to valley", "North to south", "Ocean toward the land", "Land toward the ocean"]}, {"q": "The bending of winds caused by Earth's rotation is called the:", "options": ["Sea breeze", "Greenhouse effect", "Doppler effect", "Coriolis effect"]}, {"q": "The natural greenhouse effect is important because it:", "options": ["Creates the ozone layer", "Causes earthquakes", "Keeps Earth warm enough for life", "Makes wind"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.2: Energy, Wind and Global Circulation$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,2,3,2}'::int[], array[$j$Air moves toward lower pressure.$j$,$j$Land warms faster, and cooler sea air flows in.$j$,$j$Moving air curves to the right in the Northern Hemisphere.$j$,$j$Gases absorb and return some heat.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.2: Energy, Wind and Global Circulation$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 23, $j$Check 5.3: Water in the Air: Clouds, Precipitation and Fronts$j$, $j${"questions": [{"q": "The process that changes liquid water into water vapor is:", "options": ["Evaporation", "Runoff", "Precipitation", "Condensation"]}, {"q": "Clouds form when water vapor:", "options": ["Condenses into tiny droplets", "Evaporates", "Freezes into rocks", "Runs off the land"]}, {"q": "Tall, towering storm clouds that bring thunderstorms are:", "options": ["Fog", "Stratus clouds", "Cirrus clouds", "Cumulonimbus clouds"]}, {"q": "A cold front usually brings:", "options": ["Showers or thunderstorms followed by cooler air", "No change in weather", "A long hot dry spell", "Days of steady drizzle"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.3: Water in the Air: Clouds, Precipitation and Fronts$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,0,3,0}'::int[], array[$j$Heat turns liquid water into vapor.$j$,$j$Cooling air reaches its dew point.$j$,$j$Cumulonimbus clouds can reach the top of the troposphere.$j$,$j$Cold air lifts warm air quickly.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.3: Water in the Air: Clouds, Precipitation and Fronts$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 24, $j$Check 5.4: Severe Weather, Hurricanes and Safety$j$, $j${"questions": [{"q": "A hurricane needs which of the following to form and grow?", "options": ["Warm ocean water", "Cold ocean water", "Dry desert air", "Mountains"]}, {"q": "A hurricane warning means hurricane conditions are:", "options": ["Expected within about 36 hours", "Over", "Possible within about 48 hours", "Not possible this year"]}, {"q": "The most dangerous part of a hurricane is usually the:", "options": ["Thunder", "Eye", "Storm surge", "Rainbow"]}, {"q": "If you hear thunder, the safest action is to:", "options": ["Go indoors", "Stand under a tree", "Swim", "Hold up an umbrella"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.4: Severe Weather, Hurricanes and Safety$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,0,2,0}'::int[], array[$j$Warm water, at least about 26.5 degrees Celsius, fuels the storm.$j$,$j$A watch means possible, and a warning means expected.$j$,$j$Rising seawater causes the most deaths.$j$,$j$When thunder roars, go indoors.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.4: Severe Weather, Hurricanes and Safety$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 25, $j$Unit Quiz 5: The Atmosphere and Weather$j$, $j${"questions": [{"q": "About what percent of dry air is oxygen?", "options": ["50 percent", "1 percent", "21 percent", "78 percent"]}, {"q": "The coldest layer of the atmosphere is the:", "options": ["Stratosphere", "Troposphere", "Thermosphere", "Mesosphere"]}, {"q": "Which global wind belt carries Florida's weather systems from west to east?", "options": ["Doldrums", "Prevailing westerlies", "Trade winds", "Polar easterlies"]}, {"q": "Relative humidity is a comparison of the water vapor in the air with:", "options": ["The air pressure", "The wind speed", "The cloud height", "The most it could hold at that temperature"]}, {"q": "Cirrus clouds are:", "options": ["Puffy and low", "Towering and dark", "Thin and wispy and high up", "Flat and gray"]}, {"q": "Which front often brings thunderstorms followed by cooler, drier air?", "options": ["Warm front", "Cold front", "Occluded front", "Stationary front"]}, {"q": "A hurricane with sustained winds of 120 miles per hour is a:", "options": ["Tropical storm", "Category 3 hurricane", "Category 5 hurricane", "Category 1 hurricane"]}, {"q": "The calm center of a hurricane is the:", "options": ["Eye", "Eyewall", "Front", "Surge"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 5: The Atmosphere and Weather$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,3,1,3,2,1,1,0}'::int[], array[$j$Oxygen is about one fifth of dry air.$j$,$j$Temperature drops to about 90 degrees below zero Celsius there.$j$,$j$In the middle latitudes the prevailing winds blow from the west.$j$,$j$Warm air can hold more vapor.$j$,$j$They are made of ice crystals.$j$,$j$Cold air pushes under warm air.$j$,$j$Category 3 runs from 111 to 129 miles per hour.$j$,$j$The strongest winds surround the eye in the eyewall.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 5: The Atmosphere and Weather$j$ on conflict (item_id) do nothing;
